using System.Management.Automation;
using OfficeIMO.Visio;

namespace PSWriteOffice.Cmdlets.Visio;

/// <summary>Adds a text box to the current Visio page.</summary>
/// <example>
///   <summary>Add a diagram note.</summary>
///   <prefix>PS&gt; </prefix>
///   <code>New-OfficeVisio -Path .\Notes.vsdx {
///     VisioTextBox -Text 'Generated by PSWriteOffice' -X 1in -Y 1in -Width 3in -Height 0.4in
/// }</code>
///   <para>Adds a plain text annotation to the active page.</para>
/// </example>
[Cmdlet(VerbsCommon.Add, "OfficeVisioTextBox")]
[Alias("VisioTextBox")]
[OutputType(typeof(VisioShape))]
public sealed class AddOfficeVisioTextBoxCommand : OfficeVisioShapeCmdlet {
    /// <summary>Retains the native textbox dimensions.</summary>
    public AddOfficeVisioTextBoxCommand() { Height = OfficeIMO.OfficeLength.Inches(0.5); }

    /// <summary>Text placed inside the shape.</summary>
    [Parameter(Mandatory = true, Position = 0)]
    public string Text { get; set; } = string.Empty;

    /// <inheritdoc />
    protected override VisioShape CreateShape(VisioPage page) =>
        page.AddTextBox(X.ToInches(), Y.ToInches(), Width.ToInches(), Height.ToInches(), Text, VisioMeasurementUnit.Inches);
}
